  tries:['A ∪ B의 원소 개수가 n(A) + n(B) − n(A ∩ B)와 같은지 확인해 보세요','연산을 (A ∪ B)ᶜ로 바꾸고 Aᶜ ∩ Bᶜ와 같은 원소인지 비교해 보세요','A의 원소를 B와 겹치지 않게 써서 서로소인 두 집합을 만들어 보세요','B를 A의 부분집합으로 바꾸면 A ∩ B와 A ∪ B는 어떻게 되나요?'],
  hint:'아래 칸에 원소를 쉼표로 구분해서 써 보세요.', noPlay:true,
  params:[txt('A','집합 A의 원소','1, 2, 3, 4, 5, 6',60),txt('B','집합 B의 원소','4, 5, 6, 7, 8',60),{id:'N',l:'전체집합 U = {1, 2, …, N}',min:6,max:30,step:1,val:12},
    {id:'op',l:'색칠할 부분',type:'seg',opts:[['union','A ∪ B'],['inter','A ∩ B'],['diffA','A − B'],['diffB','B − A'],['compA','Aᶜ'],['compU','(A ∪ B)ᶜ']],val:'union'}],
  cols:[{k:'nA',l:'n(A)',d:0},{k:'nB',l:'n(B)',d:0},{k:'nI',l:'n(A∩B)',d:0},{k:'nU',l:'n(A∪B)',d:0}], gx:'nI', gy:'nU',
  reset:function(){},
  draw:function(g,W,Hh){ var p=this.p, d=sets(p), G=geom(W,Hh), L=layout(W,Hh,d.reg), hi={}; OPS[p.op][1].forEach(function(k){ hi[k]=1; });
    function inC(x,y){ g.beginPath(); g.arc(x,y,G.R,0,TAU); g.clip(); } function outC(x,y){ g.beginPath(); g.rect(0,0,W,Hh); g.arc(x,y,G.R,0,TAU); g.clip('evenodd'); }
    H.rrect(g,G.ur.l,G.ur.t,G.ur.w,G.ur.h,12); g.strokeStyle=TH.dim; g.lineWidth=1.5; g.stroke();
    var regs={a:[[G.ax,0],[G.bx,1]],ab:[[G.ax,0],[G.bx,0]],b:[[G.bx,0],[G.ax,1]],o:[[G.ax,1],[G.bx,1]]};
    Object.keys(regs).forEach(function(k){ if(!hi[k]) return; g.save(); g.beginPath(); g.rect(G.ur.l,G.ur.t,G.ur.w,G.ur.h); g.clip(); regs[k].forEach(function(c){ if(c[1]===0) inC(c[0],G.cy); else outC(c[0],G.cy); }); g.fillStyle='rgba(255,201,60,.30)'; g.fillRect(0,0,W,Hh); g.restore(); });
    [[G.ax,C.blu,'A'],[G.bx,C.or,'B']].forEach(function(c){ g.beginPath(); g.arc(c[0],G.cy,G.R,0,TAU); g.strokeStyle=c[1]; g.lineWidth=3; g.stroke(); H.text(g,c[2],c[0]+(c[2]==='A'?-G.R*0.78:G.R*0.78),G.cy-G.R-1,{al:'center',size:16,w:800,c:c[1]}); });
    H.text(g,'U',G.ur.l+10,G.ur.t+14,{size:15,w:800,c:TH.dim});
    var inRes={}; d.res.forEach(function(x){ inRes[x]=1; });
    Object.keys(d.reg).forEach(function(k){ d.reg[k].forEach(function(x,i){ var q=L.pts[k][i]; if(!q) return; var on=!!inRes[x]; H.text(g,String(x),q[0],q[1],{al:'center',size:Math.max(11,Math.min(16,L.s*0.55)),w:on?800:500,c:on?C.fry:TH.dim}); }); });
    var miss=0; Object.keys(d.reg).forEach(function(k){ miss+=Math.max(0,d.reg[k].length-L.pts[k].length); }); if(miss) H.text(g,T('원소가 너무 많아 일부를 그리지 못했어요'),W/2,Hh-14,{al:'center',size:12,c:C.red}); },
  read:function(){ var p=this.p, d=sets(p), nA=d.A.length, nB=d.B.length, nI=d.reg.ab.length, nU=nA+nB-nI, ok=d.reg.a.length+d.reg.ab.length+d.reg.b.length===nU;
    var inter=d.reg.ab, compU=d.reg.o, cA=d.reg.b.concat(d.reg.o).sort(function(a,b){ return a-b; }), cB=d.reg.a.concat(d.reg.o).sort(function(a,b){ return a-b; }), cc=cA.filter(function(x){ return cB.indexOf(x)>=0; });
    return [['A',setStr(d.A),'','wide'],['B',setStr(d.B),'','wide'],[OPS[p.op][0]+' =',setStr(d.res),'','wide hl'],['n(A), n(B)',nA+', '+nB,''],['n(A ∩ B)',String(nI),''],['n(A ∪ B)',nA+' + '+nB+' − '+nI+' = '+nU,'','ok wide'],
      ['n(Aᶜ)',String(d.N-nA),''],['드모르간 (A∪B)ᶜ = Aᶜ ∩ Bᶜ',setStr(compU)===setStr(cc)?'성립해요':'?','','th'],['포함 관계',nI===nA&&nA<=nB?(nA===nB?'A = B':'A ⊂ B'):nI===nB?'B ⊂ A':nI===0?'서로소 (A ∩ B = ∅)':'어느 쪽도 포함하지 않아요','','wide']]; },
  record:function(){ var d=sets(this.p), nA=d.A.length, nB=d.B.length, nI=d.reg.ab.length; return {nA:nA, nB:nB, nI:nI, nU:nA+nB-nI}; },
  ai:function(){ var p=this.p, d=sets(p); return 'Venn diagram on U = {1..'+p.N+'}. A = '+setStr(d.A)+', B = '+setStr(d.B)+'. Highlighted region '+OPS[p.op][0]+' = '+setStr(d.res)+'. n(A) = '+d.A.length+', n(B) = '+d.B.length+', n(A and B) = '+d.reg.ab.length+', n(A or B) = '+(d.A.length+d.B.length-d.reg.ab.length)+'.'; }
