    fnPlot(g,v,function(x){ return f(p,x); },C.fry,3.2); fnPlot(g,v,function(x){ return inv(p,x); },C.cyan,3.2);
    var y0=f(p,p.x0); H.seg(g,v.sx(p.x0),v.sy(y0),v.sx(y0),v.sy(p.x0),TH.dim,1.3,[4,4]); H.dot(g,v.sx(p.x0),v.sy(y0),6.5,C.or,TH.stage); H.dot(g,v.sx(y0),v.sy(p.x0),6.5,C.grn,TH.stage);
