  hint:'곡선 위의 점 P를 끌어 보세요.', noPlay:true,
  params:[{id:'dir',l:'열린 방향',type:'seg',opts:[['h','좌우 (x²/a² − y²/b² = 1)'],['v','위아래 (y²/a² − x²/b² = 1)']],val:'h'},{id:'a',l:'a',min:1,max:6,step:0.5,val:3,d:1},{id:'b',l:'b',min:1,max:6,step:0.5,val:2,d:1},
    {id:'br',l:'점 P가 있는 갈래',type:'seg',opts:[['r','첫째 갈래'],['l','둘째 갈래']],val:'r'},{id:'s',l:'점 P의 위치',min:-2.5,max:2.5,step:0.05,val:1,d:2},{id:'as',l:'점근선 보이기',type:'check',val:true}],
  cols:[{k:'a',l:'a',d:1},{k:'b',l:'b',d:1},{k:'d1',l:'PF′',d:4},{k:'d2',l:'PF',d:4},{k:'df',l:'|PF − PF′|',d:4}], gx:'d1', gy:'df',
  reset:function(){},
  draw:function(g,W,Hh){ var p=this.p, k=geo(p), r=R4(W,Hh), m=Math.max(10,k.c+2), v=S.v=H.view(r,-m,m,-m,m,{equal:true}); H.axes(g,v);
    if(p.as){ var sl=p.b/p.a; [1,-1].forEach(function(sg2){ var A=toW(p,[-40,-40*sl*sg2]), B=toW(p,[40,40*sl*sg2]); H.seg(g,v.sx(A[0]),v.sy(A[1]),v.sx(B[0]),v.sy(B[1]),C.vio,1.5,[6,5]); }); }
    clip(g,v,function(){ [1,-1].forEach(function(sg2){ var pts=[]; for(var s=-4;s<=4;s+=0.02){ var q=toW(p,[sg2*p.a*Math.cosh(s),p.b*Math.sinh(s)]); pts.push([v.sx(q[0]),v.sy(q[1])]); } H.line(g,pts,C.fry,3.2); }); });
    H.seg(g,v.sx(k.F1[0]),v.sy(k.F1[1]),v.sx(k.P[0]),v.sy(k.P[1]),C.cyan,2.2); H.seg(g,v.sx(k.F2[0]),v.sy(k.F2[1]),v.sx(k.P[0]),v.sy(k.P[1]),C.pink,2.2);
    H.dot(g,v.sx(k.F1[0]),v.sy(k.F1[1]),6,C.grn,TH.stage); H.dot(g,v.sx(k.F2[0]),v.sy(k.F2[1]),6,C.grn,TH.stage); H.dot(g,v.sx(k.P[0]),v.sy(k.P[1]),7,C.or,TH.stage);
    tag(g,'F′',v.sx(k.F1[0])+8,v.sy(k.F1[1])+16,C.grn); tag(g,'F',v.sx(k.F2[0])+8,v.sy(k.F2[1])+16,C.grn); tag(g,'|PF′ − PF| = |'+num(k.d1,3)+' − '+num(k.d2,3)+'| = '+num(Math.abs(k.d1-k.d2),3),r.l+8,r.t+16,C.fry); },
  read:function(){ var p=this.p, k=geo(p), a2=num(p.a*p.a,2), b2=num(p.b*p.b,2); return [['식',p.dir==='h'?'x²/'+a2+' − y²/'+b2+' = 1':'y²/'+a2+' − x²/'+b2+' = 1','','wide hl'],['초점까지의 거리 c = √(a² + b²)',num(k.c,4),''],['초점',p.dir==='h'?'(±'+num(k.c,3)+', 0)':'(0, ±'+num(k.c,3)+')','','ok'],
    ['|PF − PF′|',num(Math.abs(k.d1-k.d2),4),'','hl'],['2a',num(2*p.a,4),'','th'],['점근선',p.dir==='h'?'y = ±'+num(p.b/p.a,3)+'x':'y = ±'+num(p.a/p.b,3)+'x','','wide'],['이심률 e = c/a',num(k.e,4),'']]; },
  record:function(){ var p=this.p, k=geo(p); return {a:p.a, b:p.b, d1:k.d1, d2:k.d2, df:Math.abs(k.d1-k.d2)}; },
