  record:function(){ var k=calc(this.p); return {dot:k.dot, th:isFinite(k.th)?k.th:NaN, la:k.la, lb:k.lb}; },
  ai:function(){ var p=this.p, k=calc(p); return 'Vectors a = ('+p.ax+', '+p.ay+'), b = ('+p.bx+', '+p.by+'). a+b = ('+k.sum+'), a-b = ('+k.dif+'). Dot product '+fmt(k.dot,3)+', angle '+fmt(k.th,2)+' deg, |a| = '+fmt(k.la,3)+', |b| = '+fmt(k.lb,3)+', projection of b on a '+fmt(k.proj,3)+'.'; },
  down:function(x,y){ if(!S.v) return false; var p=this.p, ba=Math.hypot(S.v.sx(p.ax)-x,S.v.sy(p.ay)-y), bb=Math.hypot(S.v.sx(p.bx)-x,S.v.sy(p.by)-y); if(Math.min(ba,bb)>26) return false; S.drag=ba<=bb?'a':'b'; return true; },
